#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    int n, m;
    std::cin >> n >> m;
    std::vector<int> factorial(n + 1);
    factorial[0] = n;
    for (int i = 1; i < n; i++) {
        long long temp_val = (long long)factorial[i - 1] * (n - i);
        factorial[i] = (int)(temp_val % m);
    }

    int size = n * (n - 1) + 1;
    std::vector<int> dp(size, 0);
    int middle = (n * (n - 1)) / 2;
    std::vector<int> temp_vec(dp);
    dp[middle] = 1;
    int answer = 0;

    for (int i = n - 1; i >= 0; i--) {
        int c = n - 1 - i;
        temp_vec = dp;
        std::fill(dp.begin(), dp.end(), 0);
        int limit = (c * (c - 1)) / 2;
        int count = 0;

        for (int cur = -c; cur < 0; cur++) {
            int pairs = c + cur + 1;
            for (int j = middle - cur + 1; j <= middle + limit; j++) {
                if (j >= 0 && j < size) {
                    long long temp_product = (long long)temp_vec[j] * pairs;
                    count = (int)((count + temp_product) % m);
                }
            }
        }

        int mult = (i == 0) ? 1 : factorial[i - 1];
        long long temp_answer = (long long)answer + (long long)count * mult;
        answer = (int)(temp_answer % m);

        for (int j = middle - limit; j <= middle + limit; j++) {
            if (j >= 0 && j < size) {
                int c = n - 1 - i;
                for (int cur = -c; cur <= c; cur++) {
                    int idx = j + cur;
                    if (idx >= 0 && idx < size) {
                        int pairs = c - abs(cur) + 1;
                        long long add_val = (long long)pairs * temp_vec[j];
                        dp[idx] = (int)((dp[idx] + add_val) % m);
                    }
                }
            }
        }
    }

    std::cout << answer << std::endl;
    return 0;
}
